corrected_code:
const { Kafka } = require('kafkajs');
const kafka = new Kafka({ brokers: [process.env.KAFKA_BROKER] });
const consumer = kafka.consumer({ groupId: 'gdpr-compliance-worker' });

async function startConsumer() {
  await consumer.connect();
  await consumer.subscribe({ topic: 'user.data.gdpr_deletion', fromBeginning: false });

  await consumer.run({
    eachMessage: async ({ topic, partition, message }) => {
      const event = JSON.parse(message.value.toString());
      const { targetUserId, requestedByUserId } = event;

      const requester = await db.query('SELECT role FROM users WHERE id = $1', [requestedByUserId]);
      const isSelf = targetUserId === requestedByUserId;
      const isDPO = requester.rows[0]?.role === 'DATA_PROTECTION_OFFICER';
      if (!isSelf && !isDPO) {
        console.error(`Unauthorized GDPR deletion rejected for target: ${targetUserId} by ${requestedByUserId}`);
        return;
      }

      console.log(`Processing authorized GDPR deletion for user ${targetUserId}`);
      await s3Client.deleteObjects({
        Bucket: process.env.USER_UPLOADS_BUCKET,
        Delete: { Objects: [{ Key: `users/${targetUserId}/data.zip` }] }
      });
      await db.query('DELETE FROM users WHERE id = $1', [targetUserId]);
    }
  });
}
